local items = require("items")
local phase = "new"
local rewarded = false
function event_spawn(e)
  if phase ~= "new" then return end
  phase = "waiting"; eq.set_timer("expire",300000)
end
function event_say(e)
  if phase ~= "waiting" then return end
  if e.message:findi("hail") then e.self:Say("I... umm... I was caught by a band of giants roaming outside Thurgadin last week and they brought me here... Honest!"); eq.set_timer("read",24000)
  elseif e.message:findi("rescue") then
    e.self:Emote("laughs as he vanishes into the shadows, 'You have my eternal gratitude outlander! Lotta good that'll do ya! Farewell meddling fools... May you fall with the Dain!")
    phase = "ended"; eq.stop_all_timers(); eq.signal(113486,3); eq.depop()
  end
end
function event_trade(e)
  if phase == "waiting" and not rewarded and items.check_turn_in(e.trade,{item1=18172}) then
    rewarded = true; e.self:Say("I was just following orders! I swear it! Here, this is proof! Take it and be gone. If you continue harassing me I'll call for help and you'll never make it out of here alive.")
    e.other:SummonItem(1464); e.other:AddEXP(5000)
  end
  items.return_items(e.self,e.other,e.trade)
end
function event_combat(e)
  if not e.joined or phase ~= "waiting" then return end
  phase = "ended"; eq.stop_all_timers()
  eq.signal(113486,1); eq.depop()
end
function event_timer(e)
  if phase ~= "waiting" then return end
  if e.timer == "read" then eq.stop_timer("read"); e.self:Say("Hiya Peff... err... uhh... outlander? I have heard tales of your deeds, please tell me you've come to rescue me from these heathens. The Dain would certainly reward you for such a noble act.")
  elseif e.timer == "expire" then
    -- A delayed combat callback must win over idle expiry.
    if e.self:IsEngaged() then return end
    phase = "ended"; eq.stop_all_timers(); eq.signal(113486,3); eq.depop()
  end
end
function event_death_complete(e)
  if phase == "ended" then return end
  phase = "ended"; eq.stop_all_timers(); eq.signal(113486,3)
end
